<?php declare(strict_types=1);
use Kulturhus\Verein\{Finance,FinanceReports,DatevExport,Documents,InvoiceApprovals};

// Independent clubs make the actual DATEV batch complete and free of unrelated
// deliberately unclassified domain fixtures. Nothing is filtered out to pass it.
foreach(['income','expense']as$postKind){
    $club='own-shared-datev-'.$postKind;$actorId=$club.'-admin';$db->prepare('INSERT INTO clubs VALUES(?,?)')->execute([$club,'Own exact shared DATEV originals']);$db->prepare("INSERT INTO actors(id,club_id,role,is_superuser) VALUES(?,?,'treasurer',1)")->execute([$actorId,$club]);$ledger=new Finance($db,$actorId);$account=$ledger->createAccount('Own actual coded shared bank','offline','1000','2020-01-01');$originals=[];
    $image=imagecreatetruecolor(32,32);ob_start();imagepng($image);$png=ob_get_clean();imagedestroy($image);$docs=new Documents($db,$actorId);
    foreach([['100.01',['60.01','40']],['49.99',['30','19.99']]]as$i=>[$amount,$parts]){
        $positions=[];foreach($parts as$j=>$part)$positions[]=['description'=>'Own shared coded original '.$i.' item'.$j,'amount'=>$part,'sphere'=>'1','account'=>$postKind==='expense'?'68150':'40000','tax_rate'=>'0','input_tax'=>$postKind==='expense'?'none':'unknown'];
        $id=$ledger->createEntry(['kind'=>$postKind,'category'=>'general','description'=>'Own shared coded original '.$i,'amount'=>$amount,'counterparty'=>'Own actual original payer','document_date'=>'2026-01-20','due_date'=>'2026-01-20','positions'=>$positions],$key());$originals[]=$id;
        $docs->upload('own-coded-original-'.$i.'.png',$png,['title'=>'Own actual coded original '.$i,'kind'=>'invoice','scope'=>'finance','links'=>['entry:'.$id]],$key());if($postKind==='expense'){$approval=new InvoiceApprovals($db,$actorId);$state=$approval->state($id);$approval->approve($id,$state['hash'],$state['decision_id'],$key(),true);}
    }
    $source=$ledger->createTransaction(['account'=>$account,'direction'=>$postKind==='expense'?'expense':'income','booked_on'=>'2026-01-23','amount'=>'150','description'=>'Own actual shared coded original payment'],$key());foreach($originals as$i=>$id)$ledger->allocate($source,(int)$ledger->transactionDetail($source)['version'],$id,(int)$ledger->entry($id)['version'],$i===0?'100.01':'49.99',$key());$returned=$ledger->createTransaction(['account'=>$account,'direction'=>$postKind==='expense'?'income':'expense','booked_on'=>'2026-01-24','amount'=>'150','description'=>'Own already recorded actual coded shared return'],$key());$reason='Own all coded original receipts fully corrected';$review=$ledger->groupReversalReview($source,$returned,$reason);$ledger->reversePaymentGroup($source,(int)$review['review']['source']['transaction']['version'],$returned,(int)$review['review']['returned']['version'],$reason,$key(),$review['hash'],true);
    $before=$whole();$report=(new FinanceReports($db,$actorId))->journal(['from'=>'2026-01-24','to'=>'2026-01-24']);$amounts=array_column($report['rows'],'amount_cents');sort($amounts,SORT_NUMERIC);$check($amounts===[1999,3000,4000,6001]&&$report['signed_total_cents']===($postKind==='expense'?15000:-15000),'actual shared '.$postKind.' refund journal retains each original cent across two receipts and four coded positions');
    $export=new DatevExport($db,$actorId);$options=['from'=>'2026-01-24','to'=>'2026-01-24','advisor'=>'1001','client'=>'1','bank_codes'=>[$account=>'18000']];$batch=$export->preview($options);$check(!$batch['errors']&&count($batch['rows'])===4&&$batch['signed_total_cents']===$report['signed_total_cents'],'actual shared '.$postKind.' refund produces a complete error-free four-position DATEV preview');$csv=$export->download($options,$batch['hash']);$lines=array_values(array_filter(explode("\r\n",substr($csv,3))));$valid=count($lines)===6;$sum=0;foreach(array_slice($lines,2)as$line){$row=str_getcsv($line,';','"','');$valid=$valid&&count($row)===125&&$row[117]==='1'&&$row[1]===($postKind==='expense'?'H':'S')&&$row[6]==='18000'&&$row[7]===($postKind==='expense'?'68150':'40000');$sum+=Finance::cents($row[0]);}$check($valid&&$sum===15000,'actual shared '.$postKind.' DATEV bytes preserve four whole original rows exact150 total original direction and general reversal marker');$check($whole()===$before,'actual shared '.$postKind.' journal DATEV preview and exact CSV download change no whole original table cell');
